<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {Compass,Network,Footprints,Settings2,Sun,Moon,ArrowUpRight,Menu,X,Check} from 'lucide-vue-next'
import {useApp} from './stores/app'
import Notice from './components/Notice.vue'
import Onboarding from './components/Onboarding.vue'
const app=useApp(),menu=ref(false),dark=ref(localStorage.getItem('unknown-theme')==='dark')
function theme(){dark.value=!dark.value;localStorage.setItem('unknown-theme',dark.value?'dark':'light');document.documentElement.classList.toggle('dark',dark.value)}
onMounted(()=>{document.documentElement.classList.toggle('dark',dark.value);app.init()})
const links=[{path:'/',name:'今日探索',icon:Compass},{path:'/map',name:'认知地图',icon:Network},{path:'/journey',name:'我的探索',icon:Footprints}]
</script>
<template><a class="skip-link" href="#main">跳转到主要内容</a><div class="site"><header class="site-header"><div class="header-inner"><RouterLink class="brand" to="/" aria-label="UnKnown 首页"><span class="brand-symbol">u<span>k</span></span><span>UnKnown<span class="brand-dot">.</span></span></RouterLink><nav class="desktop-nav" aria-label="主导航"><RouterLink v-for="link in links" :key="link.path" :to="link.path" :class="{active:$route.path===link.path}"><component :is="link.icon" :size="17"/>{{link.name}}</RouterLink></nav><div class="header-actions"><span class="local-tag"><span/>匿名探索 · 本地档案</span><button class="icon-button" @click="theme" :aria-label="dark?'切换浅色主题':'切换深色主题'"><Sun v-if="dark" :size="19"/><Moon v-else :size="19"/></button><RouterLink to="/settings" class="icon-button" aria-label="设置"><Settings2 :size="19"/></RouterLink><button class="icon-button mobile-menu" @click="menu=!menu" :aria-expanded="menu" aria-label="展开导航"><X v-if="menu" :size="22"/><Menu v-else :size="22"/></button></div></div><nav v-if="menu" class="mobile-nav" aria-label="移动导航"><RouterLink v-for="link in links" :key="link.path" :to="link.path" @click="menu=false"><component :is="link.icon" :size="17"/>{{link.name}}</RouterLink></nav></header><main id="main" class="main-shell"><Notice v-if="app.error" :error="app.error" @retry="app.init"/><Notice v-else-if="!app.ready" loading/><div v-else-if="!app.profile?.onboarding_complete" class="onboarding-placeholder" aria-hidden="true"><p class="eyebrow">WELCOME TO UNKNOWN</p><h1>给好奇心，一个新的起点。</h1></div><RouterView v-else v-slot="{Component}"><component :is="Component"/></RouterView></main><footer class="site-footer"><RouterLink class="footer-brand" to="/">UnKnown<span>.</span></RouterLink><p>Don't just discover what you like.<br class="mobile-only"> Discover what you don't know exists.</p><RouterLink to="/settings#sources">来源与透明性 <ArrowUpRight :size="14"/></RouterLink></footer><Transition name="toast"><div v-if="app.toast" class="toast-message" role="status"><Check :size="18"/>{{app.toast}}</div></Transition><Onboarding v-if="app.profile&&!app.profile.onboarding_complete"/></div></template>
